Here's the XAML and ViewModel setup:

## XAML

```xml
<RefreshView IsRefreshing="{Binding IsRefreshing}"
             Command="{Binding RefreshCommand}">
    <CollectionView ItemsSource="{Binding Items}"
                    SelectionMode="Single"
                    SelectedItem="{Binding SelectedItem, Mode=TwoWay}"
                    SelectionChangedCommand="{Binding ItemSelectedCommand}">
        <CollectionView.ItemTemplate>
            <DataTemplate x:DataType="models:MyItem">
                <Grid Padding="12" ColumnDefinitions="Auto,*">
                    <Image Source="{Binding Icon}" WidthRequest="40" HeightRequest="40" />
                    <Label Grid.Column="1" Text="{Binding Name}" VerticalOptions="Center" />
                </Grid>
            </DataTemplate>
        </CollectionView.ItemTemplate>
    </CollectionView>
</RefreshView>
```

## ViewModel Bindings

```csharp
public partial class MyViewModel : ObservableObject
{
    private readonly IMyApiService _api;
    private readonly INavigationService _nav;

    [ObservableProperty]
    private bool isRefreshing;

    [ObservableProperty]
    private MyItem? selectedItem;

    public ObservableCollection<MyItem> Items { get; } = new();

    [RelayCommand]
    private async Task Refresh()
    {
        var data = await _api.GetItemsAsync();
        Items.Clear();
        foreach (var item in data)
            Items.Add(item);
        IsRefreshing = false; // Must set false when done
    }

    [RelayCommand]
    private async Task ItemSelected()
    {
        if (SelectedItem is null) return;
        await _nav.GoToAsync("DetailPage", new Dictionary<string, object>
        {
            ["Item"] = SelectedItem
        });
        SelectedItem = null; // Reset so user can re-select same item
    }
}
```

## Key Points

| Binding | Purpose |
|---------|---------|
| `IsRefreshing` (TwoWay) | Controls the refresh spinner; set `false` when load completes |
| `Command` on RefreshView | Triggers your API reload |
| `SelectedItem` (TwoWay) | Holds the currently selected item |
| `SelectionChangedCommand` | Fires navigation logic on selection |

**Important:** Use `ObservableCollection<T>` (not `List<T>`) so the UI updates reactively. Set `SelectedItem = null` after navigating so the same item can be tapped again later.
